Medication Order.snippet:
-- grain: 1 row per medication order
SELECT patient_id, order_id, drug_name, status, ordered_at
FROM med_order WHERE status IN ('active','completed');

Medication Administration (MAR).snippet:
-- grain: 1 row per dose event
SELECT encounter_id, rxnorm, dose_value, dose_unit, route, administered_at, given_flag
FROM med_admin;

RxNorm.snippet:
-- map local name → RxNorm for rollups
SELECT local_drug_name, rxnorm_cui, tty
FROM drug_map WHERE tty IN ('SCD','SBD','IN');

Specimen & Collection Time.snippet:
SELECT specimen_type, collected_at, resulted_at, value_num
FROM lab_result
WHERE collected_at IS NOT NULL;

Abnormal / Critical Flags.snippet:
SELECT loinc, value_num, abnormal_flag
FROM lab_result
WHERE abnormal_flag IN ('H','HH','L','LL','AA');

Panel vs Analyte.snippet:
-- store analyte results; keep panel code as lineage
SELECT panel_code, loinc AS analyte, value_num
FROM lab_result WHERE panel_code = 'CBC';

Clinical Event Time vs System Time.snippet:
SELECT administered_at AS event_time, charted_at AS system_time,
       TIMESTAMPDIFF(MINUTE, administered_at, charted_at) AS chart_lag_min
FROM med_admin;

